INSERT INTO `actividades` (`id`, `codigo`, `descripcion`, `created_at`, `updated_at`) VALUES
(1, 'ACT-1.1', 'Gestión y acompañamiento especializado para la restitución del derecho a la identidad.', '2026-08-10 19:54:53', '2026-08-10 19:54:53'),
(2, 'ACT-1.2', 'Sensibilización comunitaria sobre la importancia del registro oportuno y la nacionalidad como base para la inclusión social.', '2026-08-10 19:54:53', '2026-08-10 19:54:53'),
(3, 'ACT-1.3', 'Sensibilizar y capacitar a líderes(as) en las comunidades en temas de protección de NNA y el derecho a la obtención de documentos de identidad.', '2026-08-10 19:54:53', '2026-08-10 19:54:53'),
(4, 'ACT-1.4', 'Proveer dotaciones de asistencia material a las instituciones del Estado competentes en materia de protección de NNA (papelería y artículos de oficina).', '2026-08-10 19:54:53', '2026-08-10 19:54:53'),
(5, 'ACT-2.1', 'Gestión de casos y atención de emergencia para NNA sobrevivientes de VBG y otras formas de violencia/explotación.', '2026-08-10 19:54:53', '2026-08-10 19:54:53'),
(6, 'ACT-2.2', 'Implementación de apoyo psicosocial grupal mediante la metodología de Espacios Amigables.', '2026-08-10 19:54:53', '2026-08-10 19:54:53'),
(7, 'ACT-2.3', 'Proveer dotaciones de asistencia material a las instituciones del Estado competentes en materia de protección de NNA (equipos tecnológicos).', '2026-08-10 19:54:53', '2026-08-10 19:54:53'),
(8, 'ACT-3.1', 'Provisión de asistencia legal especializada para el acceso a derechos y servicios de protección.', '2026-08-10 19:54:53', '2026-08-10 19:54:53'),
(9, 'ACT-4.1', 'Recolección de opiniones, quejas y preguntas mediante mecanismos de retroalimentación establecidos.', '2026-08-10 19:54:53', '2026-08-10 19:54:53');
